products=[]
for slug,name,col,taste,ingredient in items:
 label=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024"><rect width="1024" height="1024" fill="#FFF4D9"/><path d="M0 40H1024M0 984H1024" stroke="{col}" stroke-width="60"/><circle cx="512" cy="715" r="160" fill="{col}"/><path d="M480 580Q480 500 590 510Q590 570 480 580" fill="#134833"/><text x="512" y="260" text-anchor="middle" font-family="Arial,sans-serif" font-weight="900" font-size="220" fill="#134833">BABI</text><text x="512" y="460" text-anchor="middle" font-family="Arial,sans-serif" font-weight="900" font-size="220" fill="#134833">JUS</text><text x="512" y="550" text-anchor="middle" font-family="Arial,sans-serif" font-weight="700" font-size="{min(60,800//len(name))}" fill="#134833">{html.escape(name.upper())}</text><text x="512" y="935" text-anchor="middle" font-family="Arial,sans-serif" font-size="26" fill="#134833">LE GOÛT DE CHEZ NOUS</text></svg>'''
 (R/'assets/labels'/f'{slug}.svg').write_text(label)
 products.append(dict(id=slug,name=name,color=col,tastingNotes=taste,ingredientConcept=ingredient,label=f'assets/labels/{slug}.svg',model=f'assets/models/{slug}.glb',photo=f'assets/products/{slug}.png' if slug in [i[0] for i in items[:6]] else None,status='concept — recette, stock et étiquetage à valider'))
(R/'data/products.json').write_text(json.dumps(products,ensure_ascii=False,indent=2))
logo='''<svg xmlns="http://www.w3.org/2000/svg" width="700" height="360" viewBox="0 0 700 360"><g fill="#134833" font-family="Arial,sans-serif" font-weight="900" text-anchor="middle"><text x="350" y="165" font-size="200" letter-spacing="-14">BABI</text><text x="350" y="325" font-size="180" letter-spacing="-10">JUS<tspan fill="#F15A32">.</tspan></text></g></svg>'''
(R/'assets/brand/logo.svg').write_text(logo)
(R/'assets/brand/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="18" fill="#134833"/><text x="32" y="47" text-anchor="middle" font-family="Arial" font-weight="bold" font-size="43" fill="#FFF4D9">B</text><circle cx="51" cy="50" r="5" fill="#F15A32"/></svg>')
for slug,c in [('corail','#F15A32'),('bissap','#A71545'),('soleil','#F7BC27'),('foret','#134833')]:
 (R/'assets/backgrounds'/f'{slug}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="1920" height="1080"><defs><radialGradient id="g"><stop stop-color="{c}"/><stop offset="1" stop-color="#FFF4D9"/></radialGradient><filter id="n"><feTurbulence type="fractalNoise" baseFrequency=".8" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/></filter></defs><rect width="1920" height="1080" fill="url(#g)"/><rect width="1920" height="1080" opacity=".035" filter="url(#n)"/></svg>')
print('Catalogue:',len(products),'saveurs')
